import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { expectSectionIndex } from "../../../../testing/index.js";
import SectionedView from "./SectionedView.js";
import type { SectionedViewSection } from "./types.js";

/** Three sections, in the order a page passes them. */
const SECTIONS: readonly SectionedViewSection[] = [
  { id: "usage", title: "Usage", content: <p>When to use it.</p> },
  { id: "anatomy", title: "Anatomy", content: <p>Its parts.</p> },
  { id: "changes", title: "Changes", content: <p>What changed.</p> },
];

/** A page's own header, with its level-1 heading. */
const HEADER = (
  <header>
    <h1>Button</h1>
  </header>
);

describe("SectionedView", () => {
  it("lists exactly the sections it was given", () => {
    const { container } = render(
      <SectionedView header={HEADER} sections={SECTIONS} />,
    );
    const root = container.firstElementChild;
    if (root === null) throw new Error("the view rendered nothing");
    expectSectionIndex(root, SECTIONS);
    expect(
      screen.getByRole("navigation", { name: "On this page" }),
    ).toBeInTheDocument();
  });

  it("gives every section its level-2 heading, which labels the section", () => {
    render(<SectionedView header={HEADER} sections={SECTIONS} />);
    for (const { id, title } of SECTIONS) {
      const heading = screen.getByRole("heading", { level: 2, name: title });
      expect(heading.id).toBe(id);
      expect(
        screen.getByRole("region", { name: title }).firstElementChild,
      ).toBe(heading);
    }
  });

  it("places the header, the facts in the aside, and the body before the sections", () => {
    const { container } = render(
      <SectionedView facts={<p>Facts</p>} header={HEADER} sections={SECTIONS}>
        <p>Example</p>
      </SectionedView>,
    );
    const root = container.firstElementChild;
    expect(root?.tagName).toBe("ARTICLE");
    expect([...(root?.children ?? [])].map((child) => child.className)).toEqual(
      ["header", "aside", "content"],
    );
    expect(root?.querySelector(":scope > .header > header")).not.toBeNull();
    expect(
      [...(root?.querySelector(":scope > .aside")?.children ?? [])].map(
        (child) => child.className,
      ),
    ).toEqual(["contents", "facts"]);
    expect(root?.querySelectorAll(".facts")).toHaveLength(1);
    expect(root?.querySelector(".facts")?.textContent).toBe("Facts");
    expect(root?.textContent?.split("Facts")).toHaveLength(2);
    const content = root?.querySelector(":scope > .content");
    expect(content?.firstElementChild?.className).toBe("body");
    expect(content?.firstElementChild?.textContent).toBe("Example");
  });

  it("renders no index with no section, and no aside with no facts either", () => {
    const { container, rerender } = render(
      <SectionedView facts={<p>Facts</p>} header={HEADER} sections={[]} />,
    );
    expect(container.querySelector(".contents")).toBeNull();
    expect(container.querySelector(".aside > .facts")).not.toBeNull();
    expectSectionIndex(container, []);

    rerender(<SectionedView header={HEADER} sections={[]} />);
    expect(container.querySelector(".aside")).toBeNull();
  });

  it.each([
    ["null", null],
    ["false", false],
    ["the empty string", ""],
  ])("renders no facts and no body region when given %s", (_name, node) => {
    const { container } = render(
      <SectionedView facts={node} header={HEADER} sections={SECTIONS}>
        {node}
      </SectionedView>,
    );
    expect(container.querySelector(".facts")).toBeNull();
    expect(container.querySelector(".body")).toBeNull();
    expect(container.querySelector(".aside > .contents")).not.toBeNull();
  });

  it.each([
    ["an empty id", [{ id: "", title: "Usage", content: null }]],
    [
      "a repeated id",
      [
        { id: "usage", title: "Usage", content: null },
        { id: "usage", title: "Usage again", content: null },
      ],
    ],
  ])("throws on %s", (_name, sections) => {
    expect(() =>
      render(<SectionedView header={HEADER} sections={sections} />),
    ).toThrow(/is empty or repeated/);
  });

  it("merges a consumer className after its own and passes native props", () => {
    render(
      <SectionedView
        aria-label="Page"
        className="page"
        header={HEADER}
        sections={[]}
      />,
    );
    expect(screen.getByLabelText("Page").className).toBe(
      "ds sectioned-view page",
    );
  });
});
